// Spam/Phishing Detection
const email = $input.item.json;
const text = email.text || '';
const subject = email.subject || '';
const from = email.from || '';

// Suspicious patterns
const spamKeywords = [
  'verify your account',
  'suspended account',
  'click here immediately',
  'urgent action required',
  'you have won',
  'claim your prize',
  'nigerian prince'
];

const suspiciousPatterns = [
  /password.*reset.*immediate/i,
  /account.*suspended/i,
  /verify.*identity.*now/i,
  /click.*link.*urgent/i
];

// Check for suspicious patterns
let isSpam = false;
let spamReason = '';

for (const keyword of spamKeywords) {
  if (text.toLowerCase().includes(keyword) || subject.toLowerCase().includes(keyword)) {
    isSpam = true;
    spamReason = `Contains spam keyword: ${keyword}`;
    break;
  }
}

if (!isSpam) {
  for (const pattern of suspiciousPatterns) {
    if (pattern.test(text) || pattern.test(subject)) {
      isSpam = true;
      spamReason = `Matches suspicious pattern: ${pattern}`;
      break;
    }
  }
}

// Check for suspicious sender patterns
if (!isSpam && from) {
  const suspiciousDomains = ['temp-mail.org', 'guerrillamail.com', 'mailinator.com'];
  const domain = from.split('@')[1];
  if (suspiciousDomains.some(d => domain && domain.includes(d))) {
    isSpam = true;
    spamReason = 'Suspicious sender domain';
  }
}

return {
  json: {
    ...email,
    spam_check: {
      is_spam: isSpam,
      reason: spamReason,
      checked_at: new Date().toISOString()
    }
  }
};

// Rate Limiting Check
const email = $input.item.json;
const threadId = email.threadId;
