// PII Detection for Finance Emails
const email = $input.item.json;
const text = email.text || '';
const subject = email.subject || '';

// Patterns for PII detection
const patterns = {
  ssn: /\b\d{3}-\d{2}-\d{4}\b/g,
  credit_card: /\b\d{4}[\s-]?\d{4}[\s-]?\d{4}[\s-]?\d{4}\b/g,
  bank_account: /\b\d{8,17}\b/g,
  tax_id: /\b\d{2}-\d{7}\b/g
};

const detected = {
  has_pii: false,
  types: [],
  should_redact: false
};

for (const [type, pattern] of Object.entries(patterns)) {
  if (pattern.test(text) || pattern.test(subject)) {
    detected.has_pii = true;
    detected.types.push(type);
  }
}

// If sensitive PII detected, recommend redaction
if (detected.types.includes('ssn') || detected.types.includes('credit_card')) {
  detected.should_redact = true;
}

return {
  json: {
    ...email,
    pii_check: {
      ...detected,
      checked_at: new Date().toISOString()
    }
  }
};

